docker exec infra-tfc-api-1 python3 -c "
import json
from features.scenario.scenario_content import ScenarioContent

with open('/app/seeds/silent_wake.json') as f:
    data = json.load(f)

c = ScenarioContent(**data['content'])

# Check decision_sequence references valid template IDs
template_ids = {dt.id for dt in c.decision_templates}
for ds_id in c.decision_sequence:
    assert ds_id in template_ids, f'decision_sequence ref {ds_id} not in templates'

# Check turn references
for t in c.turns:
    if t.decision_template_id:
        assert t.decision_template_id in template_ids, f'turn {t.turn_index} refs unknown template {t.decision_template_id}'
    event_ids = {e.id for e in c.events}
    for iid in t.inject_ids:
        assert iid in event_ids, f'turn {t.turn_index} refs unknown inject {iid}'

# Check event dependencies reference valid event IDs
event_ids = {e.id for e in c.events}
for e in c.events:
    for dep in e.dependencies:
        assert dep in event_ids, f'event {e.id} dependency {dep} not in events'

# Check system_effects reference valid system IDs
system_ids = {s.system_id for s in c.initial_system_states}
for dt in c.decision_templates:
    for opt in dt.options:
        for eff in opt.system_effects:
            assert eff.system_id in system_ids, f'option {opt.id} refs unknown system {eff.system_id}'

# Check forced_option_ids reference valid option IDs in same template
for dt in c.decision_templates:
    opt_ids = {o.id for o in dt.options}
    for fid in dt.forced_option_ids:
        assert fid in opt_ids, f'template {dt.id} forced_option_id {fid} not in its options'

# Verify features used
features_used = {
    'rules': len(c.rules) > 0,
    'score_tier_thresholds': len(c.score_tier_thresholds) > 0,
    'turns': len(c.turns) > 0,
    'targets_system': any(o.targets_system for dt in c.decision_templates for o in dt.options),
    'max_plays_gt_1': any(o.max_plays > 1 for dt in c.decision_templates for o in dt.options),
    'system_effects': any(len(o.system_effects) > 0 for dt in c.decision_templates for o in dt.options),
    'forced_option_ids': any(len(dt.forced_option_ids) > 0 for dt in c.decision_templates),
    'stress_delta_turn': any(dt.stress_delta != 0 for dt in c.decision_templates),
    'stress_delta_card': any(o.stress_delta != 0 for dt in c.decision_templates for o in dt.options),
    'negative_score': any(o.score < 0 for dt in c.decision_templates for o in dt.options),
    'event_dependencies': any(len(e.dependencies) > 0 for e in c.events),
    'event_duration_ms': any(e.duration_ms is not None for e in c.events),
    'event_target_roles': any(len(e.target_roles) > 0 for e in c.events),
    'event_role_descriptions': any(len(e.role_descriptions) > 0 for e in c.events),
    'issue_auto_resolve': any(i.auto_resolve_ms > 0 for i in c.issues),
    'multi_choice': any(dt.question_type == 'multi_choice' for dt in c.decision_templates),
    'max_selections': any(dt.max_selections is not None for dt in c.decision_templates),
    'decision_sequence': len(c.decision_sequence) > 0,
    'initial_system_states': len(c.initial_system_states) > 0,
    'phases': len(c.phases) > 0,
}

print('All cross-references VALID')
print()
print('Engine capacity usage:')
for feat, used in sorted(features_used.items()):
    print(f'  {\"✓\" if used else \"✗\"} {feat}')
"
